@PactTestFor(providerName = "ArticlesProvider")
class ArticleClientPactTest {
    @Pact(consumer = "article-consumer", provider = "ArticlesProvider")
    fun pact(builder: PactDslWithProvider): RequestResponsePact = builder
        .given("articles exist").uponReceiving("a request for articles")
        .path("/articles.json").method("GET").willRespondWith().status(200)
        .body(PactDslJsonBody().minArrayLike("articles").id().stringType("title")
                                .closeObject().closeArray())
        .toPact()

    @Test fun `returns article titles`(server: MockServer) { /* ArticleClient(server.url) */ }
}

