import org.springframework.cloud.contract.spec.ContractDsl.Companion.contract

contract {
    name = "should return articles"
    request { url = url("/articles"); method = GET }
    response {
        status = OK
        body = body(mapOf("articles" to listOf(mapOf("id" to 1))))
        bodyMatchers { jsonPath("$.articles[0].id", byRegex("\\d+")) }
    }
}
